import json, sys
data = json.loads(json.loads(sys.stdin.read())['result'])['data']['experiments']
for k, v in data.items():
    if 'qwen14b' in k and 'gsm8k' in k.lower():
        m = v.get('metrics', {})
        print(f\"{k}: status={v.get('conclusion','?')}, gsm8k={m.get('gsm8k_exact_match', m.get('gsm8k_acc', 'N/A'))}\")
    elif 'qwen14b' in k and any('gsm' in str(mk).lower() for mk in v.get('metrics', {}).keys()):
        m = v.get('metrics', {})
        gsm = {kk:vv for kk,vv in m.items() if 'gsm' in kk.lower()}
        print(f\"{k}: status={v.get('conclusion','?')}, gsm_metrics={gsm}\")
" 2>&1 | head -20

